function panas(x: integer): integer;
var dingin: integer;
begin
  dingin := 0;
  while (x >= 0) do begin
    dingin := dingin + 1;
    if (x mod 3 = 0) then
      x := x - 5
    else if (x mod 5 = 0) then
      x := x - 3
    else
      x := x - 1;
  end;
  panas := dingin;
end;

function ayam(a, b: integer): integer;
begin
  if b = 0 then ayam := 0
  else if b = 1 then ayam := a
  else ayam := ayam(a, b div 2) * 2 + ayam(a, b mod 2);
end;

function kucing(tikus, keju: integer): integer;
begin
  if (tikus > keju) then
    kucing := 0
  else
    kucing := kucing(tikus * 2 + 1, keju);
end;

function apaIni(kwak: integer): boolean;
var i, j: integer;
begin
  if (kwak <= 1) then
  begin
    apaIni := false;
    exit;
  end;
  for i := 2 to (kwak - 1) do
  begin
    j := 1;
    while j * i <= kwak do
    begin
      if (i * j = kwak) then
      begin
        apaIni := false;
        exit;
      end;
      j := j + 1;
    end;
  end;
  apaIni := true;
end;

function apaItu(kwok: integer): integer;
var i, kwak, kwik: integer;
begin
  kwak := kwok;
  kwik := 0;
  for i := 0 to kwak do
  begin
    if (apaIni(i) = true) then
      kwik := kwik + 1;
  end;
  apaItu := kwik;
end;

Program santuy;
var n, a, b, ambyar, f, m: integer;
data: array[1..15] of integer = (13,17,25,28,30,41,45,56,58,64,73,76,87,91,98);
begin
  n := 15; a := 1; b := n; ambyar := 0; f := 98;
  while (a <= b) do
  begin
    m := (a + b) div 2;
    ambyar := ambyar + data[m];
    if (data[m] = f) then break
    else if (data[m] < f) then
    begin
      a := m + 1;
    end else
    begin
      b := m - 1;
    end;
  end;
  writeln(ambyar);
end.
